import json, base64
from pathlib import Path

def parse_h(raw):
    pfx=b"opensip.product.v1\x00"
    rest=raw[len(pfx):]
    i=rest.index(b"\x00")
    domain=rest[:i].decode()
    rest=rest[i+1:]
    ln=int.from_bytes(rest[:8],'big')
    c=rest[8:8+ln]
    return domain, json.loads(c.decode())

def maybe(blob):
    if not isinstance(blob,str): return None
    raw=base64.b64decode(blob)
    if raw.startswith(b"opensip.product.v1\x00"):
        return parse_h(raw)
    try:
        return ("json", json.loads(raw.decode()))
    except Exception:
        try:
            return ("json-b64-was-text", json.loads(blob))
        except Exception:
            return ("bytes", raw[:200])

